def matcoords(g): return {(i,j) for i in range(4) for j in range(4) if g[i][j]}
def d4(g):
    out=[]; x=g
    for k in range(4):
        out.append((f'r{k}',x))
        out.append((f'f{k}',[list(reversed(row)) for row in x]))
        x=[list(row) for row in zip(*x[::-1])]
    return out
